{
  "name": "Bode 100频率响应分析仪",
  "name_en": "Bode 100 frequency response analyzer",
  "manufacturer": "OMICRON Lab",
  "description": "这是一台用于扫频测试的频率响应分析仪，可向被测电路注入测试信号并测量增益与相位随频率的变化。实验中常用于滤波器、放大器及控制环路的频率响应表征与传递函数测量。",
  "description_en": "This is a swept-frequency response analyzer that injects a test signal into a device under test and measures gain and phase versus frequency. It is commonly used in the lab for frequency-response characterization and transfer-function measurement of filters, amplifiers, and control loops.",
  "actions": [
    {
      "action_name": "auto-reconnect",
      "description": "重新连接到分析仪。",
      "description_en": "Reconnect to the analyzer."
    },
    {
      "action_name": "auto-configure_gain_phase_measurement",
      "description": "配置增益/相位扫频测量。",
      "description_en": "Configure a gain/phase sweep measurement."
    },
    {
      "action_name": "auto-clear_measurement",
      "description": "清除当前测量配置。",
      "description_en": "Clear the current measurement configuration."
    },
    {
      "action_name": "auto-measurement_duration",
      "description": "查询当前测量预计所需时间。",
      "description_en": "Query the estimated duration of the current measurement."
    },
    {
      "action_name": "auto-execute_measurement",
      "description": "执行已配置的测量。",
      "description_en": "Execute the configured measurement."
    },
    {
      "action_name": "auto-stop_execution",
      "description": "停止正在进行的测量。",
      "description_en": "Stop the ongoing measurement."
    },
    {
      "action_name": "auto-read_gain_phase_results",
      "description": "读取增益与相位测量结果。",
      "description_en": "Read the gain and phase measurement results."
    }
  ],
  "tag_hints": [
    "frequency response analysis",
    "network analyzer",
    "gain and phase measurement",
    "swept-sine measurement",
    "filter characterization",
    "control loop testing"
  ]
}

